> class forward_list;

#include <algorithm>
#include <cassert>
#include <iostream>
#include <numeric>
#include <string>
#include <forward_list>

int main()
{
    std::forward_list<int> nums{1, 2, 4, 8, 16};
    std::forward_list<std::string> fruits{"orange", "apple", "raspberry"};
    std::forward_list<char> empty;

    // Print forward_list nums.
    std::for_each(nums.cbegin(), nums.cend(),
                  [](const int n) { std::cout << n << ' '; });
    std::cout << '\n';

    // Sum all integers in the forward_list nums, printing only the result.
    std::cout << "Sum of nums: "
              << std::accumulate(nums.cbegin(), nums.cend(), 0) << '\n';

    // Print the first fruit in the forward_list fruits, checking if there is any.
    if (!fruits.empty())
        std::cout << "First fruit: " << *fruits.cbegin() << '\n';

    if (empty.cbegin() == empty.cend())
        std::cout << "forward_list ‘empty’ is indeed empty.\n";

    // Modify the first element in nums.
    *nums.begin() = 32;
    assert(*nums.cbegin() == 32);
}

